// Des: Tests for the doctor
// Flo: all labels found on the fake site > a renamed label is reported MISSING with exit Drift > one job by name, url jobs need --url > old Chrome flagged
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-doct-main-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const doct = @import("ru-doct-main.zig"); const cfgz = @import("cf-conf-load.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
test "every job page on the fake site passes the doctor" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; rig.conf.base_bizz_main = rig.base(); var cx = rig.ctx(.read); const okay = try doct.doctor(&cx, "", ""); try std.testing.expect(okay >= 12); try std.testing.expect(has(&rig, "doctor: ")); if (!has(&rig, " 0 missing")) std.debug.print("{s}", .{rig.sink.items}); try std.testing.expect(has(&rig, " 0 missing")); try std.testing.expect(has(&rig, "OK      browser: Chrome")); }
test "a renamed label is reported MISSING and the doctor fails with Drift" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; rig.conf.base_bizz_main = rig.base(); rig.conf.retr_coun_maxz = 1; var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{\"labl_over\":{\"noti_mark\":[\"Zzz Nothing Here\"]}}"); rig.conf.labl_over = conf.labl_over; var cx = rig.ctx(.read); try std.testing.expectError(error.Drift, doct.doctor(&cx, "", "")); try std.testing.expect(has(&rig, "MISSING noti-mark: noti_mark")); try std.testing.expect(has(&rig, "OK      post-photo")); }
test "one job by name; url jobs need --url, then work with one" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 1; rig.conf.base_bizz_main = rig.base(); var cx = rig.ctx(.read); try std.testing.expectEqual(@as(u32, 0), (doct.doctor(&cx, "post-react", "") catch 99)); try std.testing.expect(has(&rig, "SKIP    post-react: needs --url")); rig.sink.clearRetainingCapacity(); try std.testing.expectEqual(@as(u32, 1), try doct.doctor(&cx, "post-react", "/posts/1")); try std.testing.expect(has(&rig, "OK      post-react: reac_btnz")); }
test "a browser older than the minimum is flagged" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.brow_vers_minz = 9999; var cx = rig.ctx(.read); try std.testing.expectError(error.Drift, doct.doctor(&cx, "noti-mark", "")); try std.testing.expect(has(&rig, "older than brow_vers_minz")); }
